    return not (real == root_norm or real.startswith(root_norm + "/"))

def review_command(cmd, root):
    verdict, reasons = "allow", []
    for pat, why in BLOCK_RULES:
        if re.search(pat, cmd):
            reasons.append(f"[block] {why}")
            verdict = "block"
